def transform(df):
    import re
    def clean_revenue(value):
        value = value.replace(',', '')
        value = re.sub(r'\$|\€|\£', '', value)
        value = re.sub(r'k', '000', value)
        value = re.sub(r'm', '000000', value)
        try:
            return float(value)
        except ValueError:
            return np.nan
    df['Revenue'] = df['Revenue'].apply(clean_revenue)
    return df

